    'g.load.tips': [
      'Dörfer sind nie weit — das ⌂ unter der Minikarte zeigt zum nächsten.',
      'Rechtsklick auf jemanden im Dorf: reden, tauschen, helfen oder etwas schenken.',
      'Die Baumeister im Dorf bauen mit der Zeit neue Häuser — ist eins fertig, zieht eine Familie ein.',
      'Im Reiter Voxel-Häuser gibt es Wände, Dächer und Fenster aus Mini-Voxeln, die sich selbst verzieren.',
      'Voxel-Technik: Holo-Bildschirme, Konsolen, Lichtlinien und Glaswände verbinden sich mit ihren Nachbarn.',
      'Im Kreativ- oder Zen-Modus zweimal Leertaste: fliegen. Strg halten oder zweimal W: schneller.',
      'Zen-Bauen: keine Monster, kein Schaden, kein Hunger. Zeit und Wetter hältst du im Pause-Menü an.',
      'Über den Lavendelfeldern ragen dunkle Felsnadeln auf — ihre Adern glimmen nachts.',
      'Ätherflüsse sind flüssige Energie: mit einem Eimer abfüllen, für die Sternglut-Technik.',
      'Mittelklick auf einen Block holt ihn in deine Schnellleiste.',
      'F2 macht ein Foto, F1 blendet das HUD aus, F5 wechselt die Kamera.',
      'M öffnet die Weltkarte, N setzt einen Wegpunkt.',
      'Der Builder Wand füllt, zieht Linien und kopiert Blöcke. Zwei Ecken mit Rechtsklick wählen.',
      'Außenposten haben Startplätze — such dir ein geparktes Shuttle und setz dich ans Steuer.',
      'Meteoriten hinterlassen Krater mit einem glühenden Kern.',
      'Grafik-Stufen findest du unter Einstellungen → Grafik; „Niedrig“ läuft fast überall.',
      'Tipp /help in den Chat für Befehle wie /time, /wetter, /give und /tp.',
    ],
