    // ---- F9 · Ultra für schwache PCs („Ultra · Leicht")
    'g.set.pUltraLite': 'Ultra · Leicht',
    'g.set.pUltraLiteTip': 'Ultras Bild für eingebaute Grafikchips (Laptop, Ryzen mit eingebauter Radeon): fernes Land aus dem Zwischenspeicher, Schatten in Kacheln, die Welt lädt im Takt, ein leichterer Wasserspiegel',
    'g.set.farCache': 'Fern-Cache (fernes Land und Himmel nur neu, wenn sich etwas ändert)',
    'g.set.farCache.tip': 'Himmel und fernes Land kommen aus einem Zwischenspeicher und wandern mit dem Blick mit — neu gezeichnet erst nach 1,5 m, 4° Drehung oder einer halben Sekunde, verteilt auf vier Bilder.',
    'g.set.shadowTakt': 'Schatten-Takt (Schatten nur dort neu, wo sich etwas ändert)',
    'g.set.shadowTakt.tip': 'Die Schattenkarte bleibt in Kacheln aktuell: nah jedes Bild, weiter weg seltener; wandert die Sonne, entsteht die neue Karte über sechs Bilder. Dieselben Schatten, viel weniger Arbeit.',
    'g.set.streamTakt': 'Welt im Takt (das Laden nimmt sich nur, was das Bild übrig lässt)',
    'g.set.streamTakt.tip': 'Neue Landstücke werden im Bild eingebaut statt dazwischen, nie länger als das Bild Zeit hat und höchstens 2 MB pro Bild; was hinter dir zurückbleibt, wird nicht mehr erzeugt.',
    'g.set.reflLite': 'Spiegelung leicht (Wasserspiegel kleiner gerechnet, Kanten scharf)',
    'g.set.reflLite.tip': 'Der Spiegel im Wasser wird mit einem Viertel der Breite gerechnet und kantengenau vergrößert; er zeigt die Welt bis 96 Blöcke, dahinter den Horizont.',
    // ---- F10 · Bandbreite (ipu.js): fünf Schalter für Grafikchips ohne eigenen Speicher — gleiches Bild, weniger Speicherverkehr (texLite: weicher, nur auf Wunsch)
    'g.set.hdrLite': 'Schlanke Lichtpuffer (HDR in 4 statt 8 Byte je Pixel)',
    'g.set.hdrLite.tip': 'Das Bild wird in einem kompakteren Lichtformat gerechnet: halb so viel Speicherverkehr für Szene, Wasserspiegel, Leuchten und Lichtstrahlen — dasselbe Bild. Hilft vor allem Grafikchips, die sich den Speicher mit dem Prozessor teilen.',
    'g.set.postLite': 'Nachbearbeitung leichter (Kopien nur bei Bedarf)',
    'g.set.postLite.tip': 'Die Kopie des Bildes für das Wasser nur, wenn Wasser im Bild ist, die Tiefenkopie nur, wenn sie gebraucht wird, Lichtstrahlen aus einem kleinen Vorbild — dasselbe Bild, weniger Arbeit.',
    'g.set.zPre': 'Laub zuerst nur in die Tiefe (Blätter, Gras, Zäune)',
    'g.set.zPre.tip': 'Blätter, Gras und Zäune werden zuerst nur in die Tiefe gezeichnet, danach mit Licht und Farbe — so wird jeder Bildpunkt einmal beleuchtet statt für jedes Blatt dahinter.',
    'g.set.texLite': 'Texturen leichter filtern (schräge Flächen weicher)',
    'g.set.texLite.tip': 'Schräge Flächen werden 2-fach statt 4-fach anisotrop gefiltert — weniger Texturarbeit für schwache Grafikchips, dafür wirken Wiesen und Hänge in der Ferne etwas weicher. Keine Voreinstellung schaltet das ein.',
    'g.set.dprLite': 'Auflösung höchstens wie der Bildschirm',
    'g.set.dprLite.tip': 'Das Bild wird nie größer gerechnet, als der Bildschirm Pixel hat (Windows-Skalierung 125 oder 150 %); bei Ultra · Leicht höchstens 1920 × 1080, den Rest vergrößert der Browser.',
    // t-material · Glanz & Spiegelungen
    'g.set.pbr': 'Glanz & Spiegelungen',
    'g.set.pbr.tip': 'Polierter Stein, Glanzfliesen, Lack und Metall spiegeln Himmel und Sonne; auf Hoch spiegeln glänzende Böden auch die Welt — schöner, kostet etwas.',
    'g.set.pbrV': ['Aus', 'Glanz', 'Glanz + Spiegel'],
    'g.set.water': 'Wasser',
    'g.set.water.tip': 'Spiegelnde Seen, türkise Untiefen, Gischt an Ufern und Wellenkämmen, Lichtnetze am Grund; hoch spiegelt das Wasser nachts Sterne und Nebel — kostet etwas.',
    'g.set.waterV': ['Einfach', 'Spiegel', 'Brillant'],
    'g.set.texHi': 'Detail-Texturen', 'g.set.texHi.tip': 'Die 16 häufigsten Materialien (Gras, Erde, Sand, Fels, Marmor, Platten, Eiche …) in doppelter Auflösung (64 × 64): feinere Körnung aus der Nähe, dieselben Farben von fern. ~0,7 MB Grafikspeicher; einmal im Hintergrund geschmiedet, danach aus dem Zwischenspeicher. Nicht im Klassisch-Look.',
    'g.aq.ul.far': 'Fern-Cache seltener neu',
    'g.aq.ul.shadow': 'Schatten-Kacheln seltener neu',
