    'g.set.l2Grade': 'Farbstimmung',
    'g.set.l2Grade.tip': 'Jede Tageszeit hat ihre Farben: die goldene Stunde warm, die Dämmerung violett, die Nacht türkis mit warmen Lampen; Leuchten glühen, die Sonne blendet sanft.',
    'g.set.magic.tip': 'Wie stark der Sternenhimmel am Tag durchscheint.',
