    'g.out.boat': ['Wer will segeln gehen?', 'Bootsfahrt! Holt eure Hüte!', 'Auf aufs Wasser!'],
    'g.out.hike': ['Familienwanderung! Alle bereit?', 'Auf den Hügel, zum Picknick!', 'Kommt, Kinder — Abenteuerzeit!'],
    'g.out.kidYay': ['Juhu!!', 'Darf ich vorgehen?', 'Wettrennen bis dahin!'],
