    // ---- a-story · 📖 „Funke und die Leuchtfeuer" (src/shared/story.js, src/main/story.js, src/main/regie.js): das Buch, der Spieler der Szenen, das Tagebuch
    'story.who.funke': 'Funke',
    'story.who.ilka': 'Meisterin Ilka',
    'story.who.oskar': 'Oskar',
    'story.who.selma': 'Selma',
    'story.who.jonte': 'Kapitän Jonte',
    'story.who.lumi': 'Lumi',
    'story.c1.title': 'Funke',
    'story.c1.where': 'Die Hangarhalle → das Vorfeld',
    'story.c1.log': 'Ein kleiner Funke wacht auf — und die Welt ist dunkel geworden.',
    'story.c2.title': 'Das stille Leuchtfeuer',
    'story.c2.where': 'Der Außenposten im Canyon',
    'story.c2.log': 'Das erste Feuer flackert rot. Bring es zurück zum Leuchten.',
    'story.c3.title': 'Über den Wolken',
    'story.c3.where': 'Der Aufstieg, die Ringstation',
    'story.c3.log': 'Die Welt biegt sich weg, und über ihrem Rand blinkt etwas Rotes.',
    'story.c4.title': 'Die Monde von Amarant',
    'story.c4.where': 'Basalt und Opal',
    'story.c4.log': 'Unter dem Eis schläft ein Wächter, bis Amarant die Sonne verschluckt.',
    'story.c5.title': 'Feuer und Glas',
    'story.c5.where': 'Zinnober',
    'story.c5.log': 'Lavafontänen unter einem riesigen Planeten — und ein Leuchtfeuer aus Glas.',
    'story.c6.title': 'Das Atoll',
    'story.c6.where': 'Aquamarin',
    'story.c6.log': 'Eine versunkene Kraterstadt und die Notizen von Lumis Großvater.',
    'story.c7.title': 'Der Sprung',
    'story.c7.where': 'Der erste Sternensprung',
    'story.c7.log': 'Die Sterne rücken zusammen, und vor dir glüht ein oranger Zwerg.',
    'story.c8.title': 'Zwei Sonnen',
    'story.c8.where': 'Ein Doppelstern',
    'story.c8.log': 'Zwei Schatten, zwei Sonnenuntergänge — und ein Leuchtfeuer, das zweimal blinkt.',
    'story.c9.title': 'Im Nebel',
    'story.c9.where': 'Mitten in einem Nebel',
    'story.c9.log': 'Dort, wo die Schatten geboren wurden, ist es gar nicht dunkel.',
    'story.c10.title': 'Der rote Riese',
    'story.c10.where': 'Ein sterbender Stern',
    'story.c10.log': 'Ein letztes Leuchtfeuer auf einer Welt unter einer riesigen roten Sonne.',
    'story.c11.title': 'Echo',
    'story.c11.where': 'Am Schwarzen Loch',
    'story.c11.log': 'Echo hat zu lange ins Dunkel gelauscht. Findest du sein Lied wieder?',
    'story.c12.title': 'Heimkehr',
    'story.c12.where': 'Der Platz am Tortempel',
    'story.c12.log': 'Das Netz leuchtet wieder. Zeit für ein Fest mit Feuerwerk.',
    'story.c1.b1.1': 'Oh! Ein Mensch! Entschuldige — wie lange habe ich geschlafen?',
    'story.c1.b1.2': 'Die Leuchtfeuer sind dunkel. Alle. Ich höre nur noch Rauschen.',
    'story.c1.b1.3': 'Na sieh mal an. Der kleine Funke ist wieder wach. Pass gut auf ihn auf, ja?',
    'story.c1.b1.4': 'Hilfst du mir, sie wieder anzuzünden? Komm, ich zeig dir was!',
    'story.c1.b2.1': 'Siehst du das Land da draußen? Früher hat auf jedem Hügel ein Licht geblinkt.',
    'story.c1.b2.2': 'Dann kam die Stille. Über Nacht. Seitdem irren die Arbeitsmaschinen im Kreis.',
    'story.c1.b2.3': 'Im Canyon stand das nächste Leuchtfeuer. Ich zeig dir den Weg!',
    'story.c1.b3.1': 'Hallo? Hört mich jemand? Hier spricht Oskar, vom alten Leuchtturm.',
    'story.c1.b3.2': 'Ich habe die Feuer vierzig Jahre lang gehütet. Dort vorn, das rote Flackern — das ist eins davon.',
    'story.c1.b3.3': 'Rot heißt: Es ist verwirrt. Wir gehen hin, ganz ruhig.',
    'story.c2.b1.1': 'Da ist es. Das Leuchtfeuer flackert rot, und die Maschinen hören nur noch das Rauschen.',
    'story.c2.b1.2': 'Wir machen nichts kaputt. Wir bringen sie nur wieder zur Ruhe.',
    'story.c2.b1.3': 'Beruhige die Maschinen oder halte den Kreis — dann lenk das Licht zurück in die Lampe!',
    'story.c2.b2.1': 'Es leuchtet! Hörst du? Es singt wieder!',
    'story.c2.b2.2': 'Hier Oskar! Ich sehe ein cyanfarbenes Licht über dem Canyon — nach all den Jahren!',
    'story.c2.b2.3': 'Sag dem kleinen Funken: Selma will euch sprechen. Sie hat die alten Karten.',
    'story.c2.b2.4': 'Ein Feuer brennt. Und es gibt noch so viele!',
    'story.c2.b3.1': 'Ich bin Selma, ich zeichne Karten. Schau mal, hier — ein Leuchtfeuer, das gar nicht auf dem Boden steht.',
    'story.c2.b3.2': 'Es kreist über den Wolken, auf der Ringstation. Wer es sehen will, muss hinauf.',
    'story.c2.b3.3': 'Hinauf? Ganz hinauf? Oh, ich wollte immer wissen, wie die Welt von oben aussieht!',
    'story.c3.b1.1': 'Kapitän Jonte Wendt hier. Halt die Nase hoch, dann trägt dich der Himmel.',
    'story.c3.b1.2': 'Schau, der Horizont … er biegt sich! Die Welt ist ja rund!',
    'story.c3.b1.3': 'Weiter so. Über der Luft wartet die Ringstation. Früher hat sie uns heimgeleuchtet.',
    'story.c3.b2.1': 'Da! Über dem Rand der Welt — ein rotes Blinken!',
    'story.c3.b2.2': 'Die Ringstation. Rot heißt: Sie ruft. Jemand dort oben wartet auf Antwort.',
    'story.c3.b2.3': 'Dieses Blinken hab ich seit Jahren nicht gesehen. Gut gemacht, ihr zwei.',
    'story.c3.b3.1': 'Siehst du den großen Ringplaneten? Das ist Amarant. Seine Monde waren mal voller Leuchtfeuer.',
    'story.c3.b3.2': 'Nach Basalt und Opal bin ich jeden Tag geflogen. Dann wurde es still dort draußen.',
    'story.c3.b3.3': 'Dann fliegen wir hin! Die Monde haben lange genug im Dunkeln gewartet.',
    'story.c4.b1.1': 'So leise hier. Kein Wind, keine Vögel. Nur der Staub unter deinen Stiefeln.',
    'story.c4.b1.2': 'Und über uns hängt Amarant, riesig und still, mit seinem Ring.',
    'story.c4.b1.3': 'Hallo, hier ist Lumi aus Nova Haven! Opas Notizen sagen: Unter dem Eis von Opal schläft ein Wächter.',
    'story.c4.b2.1': 'Psst. Schau ins Eis. Da unten … ein Wächter.',
    'story.c4.b2.2': 'Sein Auge ist noch wach. Es leuchtet ganz schwach, als würde es träumen.',
    'story.c4.b2.3': 'Der Eiswächter! Opa schreibt, er wacht nur auf, wenn Amarant die Sonne verschluckt.',
    'story.c4.b2.4': 'Dann warten wir auf die Finsternis. Ich zähl mit!',
    'story.c4.b3.1': 'Es passiert! Amarant schiebt sich vor die Sonne!',
    'story.c4.b3.2': 'Jetzt schnell! Im Schatten zeigt das Eis ein Muster …',
    'story.c4.b3.3': '… eine Karte! Sie zeigt nach Zinnober, zu den Feuerbergen!',
    'story.c4.b3.4': 'Das nächste Leuchtfeuer. Fortsetzung folgt, Partner!',
    'story.offer': 'Ich empfange ein Signal … [{key}] ansehen',
    'story.remind': 'Das Signal ist noch da. [{key}] ansehen?',
